package unverified;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class ClonePair10713DifferenceFindingTest {

    private final ClonePair10713 subject = new ClonePair10713();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: exception.
     * Difference manifestation: the methods differ in thrown exceptions or normal completion.
     */
    @Test
    @BehavioralDifference(DifferenceType.EXCEPTION)
    void methodsDisagreeOnASecondOccurrenceOfTheSearchString() {
        // method1 computes the end index of the copied segment as (i - start) instead of i,
        // which is smaller than start once a second occurrence is found.
        assertThrows(StringIndexOutOfBoundsException.class, () -> subject.method1("abab", "b", "x"));
        assertEquals("axax", subject.method2("abab", "b", "x"));
    }
}
